-- ============================================================
-- ALLDATA import — customers + vehicles (7 years of history).
-- Generated from crm-2.aspx (ALLDATA Manage Online CRM export).
-- RUN IN THE SUPABASE SQL EDITOR. Wrapped in one transaction (atomic).
--
--  ############################################################
--  #  TIMING CONSTRAINT — READ BEFORE YOU RUN                 #
--  #  The clean REVERSE at the bottom of this file only works #
--  #  BEFORE any repair_order is created against an imported  #
--  #  customer or vehicle. The RO foreign keys are ON DELETE  #
--  #  RESTRICT, so once an RO points at imported data, the    #
--  #  delete is blocked. If this import looks wrong, UNDO IT  #
--  #  before anyone writes an RO.                             #
--  ############################################################
--
-- What it does (expected counts — verify after):
--   NEW customers ............ 2666
--   ENRICHED existing ........ 27  (vehicles + alldata_code stamp ONLY;
--                                   scalar fields via the separate _enrich_27 file)
--   VEHICLES imported ........ 3202
--   SKIPPED car-as-customer .. 15 codes (see review list at bottom)
--   FLAGGED ambiguous ........ 2 existing / 4 codes (see review list at bottom)
--
-- Does NOT touch the existing customers except stamping alldata_code on the
-- 27 clean matches (the intended enrichment link).
-- ============================================================
begin;

-- ── 1. columns + idempotency guards (all IF NOT EXISTS) ──
alter table public.customers add column if not exists alldata_code  text;
alter table public.customers add column if not exists source        text;
alter table public.customers add column if not exists last_invoiced date;
alter table public.vehicles  add column if not exists alldata_code  text;
alter table public.vehicles  add column if not exists source        text;
-- plain unique indexes: NULLs are distinct in Postgres, so native rows (null
-- alldata_code / null vin) never collide, and ON CONFLICT can infer them.
create unique index if not exists uq_customers_alldata_code on public.customers(alldata_code);
create unique index if not exists uq_vehicles_alldata_vin  on public.vehicles(alldata_code, vin);

-- ── 2. staging (temp; dropped at commit) ──
create temp table _stg_cust (alldata_code text, name text, business_name text, phone_primary text, phone_secondary text, email text, address_line1 text, city text, state text, postal_code text, last_invoiced date) on commit drop;

create temp table _stg_enrich (alldata_code text, match_key text) on commit drop;

create temp table _stg_veh (alldata_code text, vin text, make text, model text, plate text, plate_state text) on commit drop;

-- ── 3. transform ──
-- 3a. new customers (idempotent on alldata_code)
select name, business_name, phone_primary, phone_secondary, email, address_line1, city, state, postal_code, last_invoiced, alldata_code, 'alldata'
from _stg_cust
on conflict (alldata_code) do nothing;

-- 3b. stamp alldata_code on the clean-matched EXISTING customers (link only; NO
--     scalar overwrite here — that's the reviewable _enrich_27 file). Matches by
--     normalized last-10 phone; ambiguous shared-phone matches are excluded.
update public.customers c
set alldata_code = e.alldata_code
from _stg_enrich e
where c.source is distinct from 'alldata'
  and c.alldata_code is null
  and ( right(regexp_replace(coalesce(c.phone_primary,''),  '\D','','g'),10) = e.match_key
     or right(regexp_replace(coalesce(c.phone_secondary,''),'\D','','g'),10) = e.match_key );

-- 3c. vehicles for new + enriched customers (linked by alldata_code)
select c.id, v.vin, v.make, v.model, v.plate, v.plate_state, v.alldata_code, 'alldata'
from _stg_veh v
join public.customers c on c.alldata_code = v.alldata_code
on conflict (alldata_code, vin) do nothing;   -- (alldata_code, null vin) rows are distinct → no-VIN cars still insert

commit;

-- ── post-run sanity (run these to check against the expected counts above) ──
-- select count(*) from public.customers where source='alldata';                       -- expect NEW count
-- select count(*) from public.customers where source is distinct from 'alldata' and alldata_code is not null;  -- expect ENRICHED count
-- select count(*) from public.vehicles  where source='alldata';                       -- expect VEHICLES count

-- ============================================================
--  EXACT REVERSE (undo the whole import). See TIMING CONSTRAINT up top.
-- ------------------------------------------------------------
--  begin;
--  delete from public.vehicles  where source = 'alldata';
--  delete from public.customers where source = 'alldata';
--  update public.customers set alldata_code = null
--    where alldata_code is not null and (source is null or source <> 'alldata');
--  commit;
-- ============================================================
